'use strict';
const MOCK_NOTICE='<div class="mock-notice">Démonstration uniquement. Aucun compte, paiement ou message réel n’est créé.</div>';
Object.assign(V,{
 'ENT-05':()=>head('Votre espace Beautify','Découvrez le parcours de création de compte.')+`<div class="account-icon">${icon('user')}</div>`+MOCK_NOTICE+form('register',field('name','Nom de démonstration',M.profile.name,'text',true)+field('email','Adresse de démonstration','mia@example.test','email',true)+check('terms','J’accepte de parcourir la création de compte simulée.'),'Créer le compte démo')+B('J’ai déjà un compte','ENT-06','secondary mt')+B('Continuer en découverte','DEC-01','text-button mt'),
 'ENT-06':()=>head('Heureuse de vous revoir','Retrouvez votre parcours de démonstration.')+`<div class="account-icon">${icon('lock')}</div>`+MOCK_NOTICE+form('login',field('email','Adresse de démonstration',M.profile.email||'mia@example.test','email',true)+`<div class="glass panel"><span class="subtle">Mot de passe simulé</span><p class="accent" style="letter-spacing:.25em;margin-top:8px">••••••••</p></div>`,'Se connecter — démo')+B('Accès oublié ?','ENT-08','text-button mt')+B('Créer un compte démo','ENT-05','secondary mt')+A('Annuler et revenir','account-cancel',{},'secondary mt'),
 'ENT-07':()=>head('Vérifier mon accès','Entrez le code de démonstration pour continuer.')+`<div class="account-icon">${icon('check')}</div>`+P('Code de démonstration : <strong class="accent">123456</strong>. Aucun code n’a été envoyé par email.')+form('verify',field('code','Code à 6 chiffres','','text',true),'Vérifier mon accès')+A('Renvoyer le code — simulation','resend-code',{},'text-button mt')+A('Annuler et revenir','account-cancel',{},'secondary mt'),
 'ENT-08':()=>head('Retrouver mon accès','Parcourez la récupération d’un accès fictif.')+form('recover',field('email','Adresse de démonstration',M.profile.email||'mia@example.test','email',true),'Envoyer le lien — simulation')+MOCK_NOTICE+B('Retour à la connexion','ENT-06','secondary mt'),
 'PRF-01':()=>head('Mon espace')+`<section class="glass mock-profile">${M.profile.avatar?imageFor(M.profile.avatar,'avatar','Ma photo de profil'):`<div class="account-icon">${icon('user')}</div>`}<div><h2>${esc(M.profile.name||'Bienvenue')}</h2><p>${M.profile.connected?'Compte démo connecté':'À votre rythme, sans compte'}</p>${B('Modifier mon profil','PRF-02','text-button')}</div></section>`+row('Mes goûts et mes besoins','Affiner ce qui m’est proposé','PRF-03','heart')+row('Mon abonnement',subscriptionLabel(),'PRF-06','star')+row('Mes commandes','Retrouver mes achats de démonstration','ACH-07','bag')+row('Photos et confidentialité','Choisir ce que je conserve','PRF-07','lock')+row('Paramètres et aide','Rappels, compte et réponses','PRF-04','settings')+(!M.profile.connected?B('Retrouver mon compte — démo','ENT-06','secondary mt'):''),
 'PRF-02':()=>{const profile=M.profileEdit||M.profile;return head('Modifier mon profil','Votre identité d’usage dans le mockup.')+form('profile',field('name','Nom d’usage — facultatif',profile.name)+field('email','Email de démonstration',profile.email,'email')+A(icon('image')+' Choisir une photo de profil','file-pick',{purpose:'profile'},'secondary')+(profile.avatar?imageFor(profile.avatar,'avatar','Portrait sélectionné pour le profil'):'')+(profile.avatar?A('Retirer ma photo de profil','avatar-remove-request',{},'text-button'):''),'Garder les modifications')+note('La photo de profil est distincte de la photo d’analyse. Modifier une adresse déclenche une vérification simulée.')},
 'PRF-03':()=>head('Mes goûts et mes besoins','Vous gardez la main. Vos anciens comptes rendus ne changeront pas.')+sec('Ce qui m’intéresse')+chips([...DOMAINS.map(x=>x[0]),'Habitudes'],'interests',(M.preferenceEdit||M.prefs).interests)+preferencesForm('preferences')+(Object.keys(M.contentFeedback||{}).length?A('Réinitialiser mes retours sur les looks','reset-feedback',{},'text-button mt'):'')+A('Retirer mes préférences','clear-prefs-request',{},'text-button mt'),
 'PRF-04':()=>head('Paramètres','Tous vos réglages, au même endroit.')+row('Rappels & notifications','Préférences simulées','PRF-05','calendar')+row('Informations personnelles','Nom et accès','PRF-02','user')+row('Abonnement','État et restauration','PRF-06','star')+row('Photos, analyses et confidentialité','Inventaire et gestion','PRF-07','lock')+row('Aide & support','Questions et contact simulé','PRF-10','spark')+row('Informations & documents','À propos et crédits','PRF-11','bookmark')+A('Se déconnecter du compte démo','logout-request',{},'secondary mt')+B('Supprimer le compte démo','PRF-09','text-button mt')+note('Beautify, Mockup complet V0.2, Français'),
 'PRF-05':()=>head('Mes rappels','Seulement les moments que vous choisissez.')+form('reminders',check('routine','Un rappel pour mes routines',M.reminders.routine)+field('routineTime','À quelle heure ?',M.reminders.routineTime||'08:00','time')+moreActions(check('analyses','Mes pistes sont prêtes',M.reminders.analyses)+check('account','Les informations de mon compte',M.reminders.account),'Autres messages'),'Garder mes choix')+note('Les rappels sont simulés dans ce prototype. Aucun envoi réel. Vous pouvez tout désactiver ici.'),
 'PRF-06':()=>head('Mon abonnement',subscriptionLabel())+panel(`<h2>${M.subscription.status==='active'?'Mon espace Premium':'Mon accès découverte'}</h2>${P(M.subscription.status==='active'?'Votre organisation complète : semaine et routines.':'Explorez vos inspirations et testez votre premier rituel.')}`)+(M.subscription.status==='active'?B('Retrouver ma semaine','ACC-02')+A('Gérer mon abonnement','manage-subscription',{},'secondary mt'):B('Ce que propose Premium','PRE-01'))+B('Retrouver un accès existant','PRE-04','text-button mt')+note('Tous les parcours sont ouverts dans ce prototype. Aucune souscription réelle.'),
 'PRF-07':()=>head('Photos & données','Ce qui est conservé dans ce mockup.')+panel(P('Les textes, les produits et les routines sont enregistrés dans ce navigateur sur cet appareil. Les images importées sont conservées en mémoire de la page. La recherche de produits envoie le nom recherché ou le code-barres à Open Beauty Facts. Les photos du scanner sont lues sur votre appareil.'))+dataInventory()+B('Exporter ou retirer des données','PRF-08')+B('Supprimer le compte démo','PRF-09','secondary mt')+B('Comprendre le fonctionnement','PRF-11','text-button mt',{document:'Données'}),
 'PRF-08':()=>head('Gérer mes données','Choisissez précisément ce que vous souhaitez exporter ou retirer.')+form('data',select('operation','Opération',['Exporter','Retirer'],'Exporter')+['Profil','Préférences','Photos','Rapports','Suivi','Enregistrés','Routines','Dressing','Commandes'].map(t=>check('data'+t,t,false)).join(''),'Vérifier ma sélection')+(M.dataStatus?panel(P(esc(M.dataStatus))):'')+note('Retirer une photo conserve le texte des rapports. Retirer un rapport le supprime aussi des comparaisons disponibles.'),
 'PRF-09':()=>head('Supprimer le compte démo','Vérifiez les conséquences avant de confirmer.')+panel(`<h3>${esc(M.profile.email||'Session de découverte')}</h3>${P('Cette action efface les données du mockup présentes dans cet onglet, y compris les favoris, rapports et commandes de démonstration.')}${P('Aucun compte réel, abonnement réel ou achat réel n’est concerné.')}`)+B('Exporter d’abord mes données','PRF-08','secondary mt')+B('Vérifier mon abonnement démo','PRF-06','secondary mt')+form('delete-account',field('confirmation','Écrivez SUPPRIMER pour confirmer','','text',true),'Supprimer les données du mockup')+B('Annuler','PRF-07','text-button mt'),
 'PRF-10':()=>head('Comment vous aider ?','Retrouvez les réponses liées à ce prototype.')+`<div class="faq">${[['Mes données sont-elles synchronisées ?','Non. Les données de ce mockup restent dans cet onglet. Les photos importées doivent être choisies à nouveau après actualisation.'],['Les analyses sont-elles réelles ?','Non. Les résultats illustrent les parcours et reprennent des exemples. Aucun calcul n’est réalisé sur votre photo.'],['Pourquoi mes favoris ne sont-ils pas dans mon plan ?','Enregistrer conserve une inspiration. Ajouter au plan active une action ou une routine distincte.'],['Un paiement peut-il être effectué ?','Non. Les prix, la carte, les transactions et les commandes sont fictifs.'],['Que se passe-t-il si je refuse une autorisation ?','Vous pouvez importer une image, utiliser l’exemple ou revenir à Découvrir.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`+sec('Demande de support — simulation')+form('support',select('topic','Sujet',['Compte','Photo','Analyse','Routine','Enregistrés','Abonnement','Données','Commande'],'Compte')+area('message','Décrivez votre demande')+`<label class="field"><span>Pièce jointe — facultative, simulée</span><input type="file" name="attachment" accept="image/*,.txt"></label>`,'Prévisualiser ma demande')+(M.tickets.length?sec('Demandes de démonstration')+M.tickets.map(t=>panel(`<strong>${esc(t.ref)}</strong>${P(esc(t.topic)+', Reçue dans le mockup')}`)).join(''):'')+note('Aucun message n’est envoyé à une équipe de support.'),
 'PRF-11':()=>head('Informations & documents')+chips(['À propos','Données','Abonnement','Crédits'],'documentTab',M.documentTab||'À propos')+panel(`<h2>${esc(M.documentTab||'À propos')}</h2>${P(({ 'À propos':'Beautify by UZMEK est présenté ici sous forme de mockup interactif. Cette version réunit les analyses cheveux, couleurs et peau, les essais coiffure et les routines. Le maquillage, la garde-robe et les tutoriels sont à venir.',Données:'Le mockup conserve les textes, produits et routines dans ce navigateur sur cet appareil. Les photos importées sont en mémoire. Le nom recherché ou le code-barres est transmis à Open Beauty Facts pour retrouver un produit. Vous pouvez exporter ou retirer vos données dans Photos & données. Les règles d’une future application réelle restent à définir.',Abonnement:'Les offres et les transactions sont fictives. Aucun prélèvement, renouvellement, essai réel ou abonnement externe n’est déclenché. Les conditions de la future offre commerciale ne sont pas définies ici.',Crédits:'Les visuels proviennent des maquettes fournies et de portraits éditoriaux générés avec IA pour ce prototype. Les textes de parcours s’appuient sur Beautify — Parcours et contenus, version 0.1. Les contenus éditoriaux supplémentaires sont des exemples pour le mockup.<br><br>Catalogue <a href="https://world.openbeautyfacts.org" target="_blank" rel="noopener noreferrer">Open Beauty Facts</a>, données <a href="https://opendatacommons.org/licenses/odbl/1-0/" target="_blank" rel="noopener noreferrer">ODbL</a>, photos <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">CC BY-SA</a>.'})[M.documentTab||'À propos'])}`)+note('Ces informations décrivent le prototype. Elles ne constituent pas des conditions contractuelles ou une politique juridique validée pour un service commercial.')+B('Contacter le support — démo','PRF-10','secondary mt')
});
function subscriptionLabel(){return ({free:'Accès découverte',active:'Premium actif — simulé',pending:'Activation en attente — simulée',failed:'Souscription échouée — simulée',expired:'Accès expiré — simulé',cancelled:'Renouvellement annulé — simulé'})[M.subscription.status]||'Statut indisponible';}
function dataInventory(){return [['Profil',M.profile.name?'Renseigné':'Sans nom'],['Préférences',M.prefs.interests.length+' centres d’intérêt'],['Photos',Object.keys(memoryPhotos).length+' images importées en mémoire'],['Rapports',M.analyses.length+' comptes rendus simulés'],['Suivi',M.observations.length+' observations, '+M.sessions.length+' séances'],['Enregistrés',M.saved.length+' contenus, '+M.collections.length+' collections'],['Dressing',M.clothes.length+' pièces']].map(([a,b])=>`<div class="data-check"><strong>${a}</strong><p>${b}</p></div>`).join('');}
Object.assign(V,{
 'PRE-01':()=>head('Moins chercher.<br>Plus profiter.','Beautify Premium, offre à tester')+`<section class="glass premium-value"><span class="eyebrow">Votre semaine, déjà pensée</span><h2>Vos looks, vos rituels,<br><span class="accent">vos moments.</span></h2><p>Quelques idées adaptées à vos envies. Un plan que vous pouvez changer. Vos favoris à portée de main.</p>${B('Voir un exemple de ma semaine','ACC-02','secondary')}</section>`+`<div class="offer-comparison"><div><span>Découverte</span><p>Explorer les inspirations, garder ses envies et commencer une routine.</p></div><div><span>Premium</span><p>Préparer sa semaine, réunir ses occasions et réutiliser ses propres tenues dans une organisation complète.</p></div></div>`+`<fieldset class="billing"><legend>Mon rythme</legend>${['monthly','yearly'].map(v=>A(`<strong>${v==='yearly'?'Annuel':'Mensuel'}</strong><span>${v==='yearly'?'59,99 € / an':'9,99 € / mois'}</span><small>${v==='yearly'?'12 mois, soit environ 5 € / mois':'Un mois pour découvrir'}</small>`,'offer',{value:v,pressed:M.subscription.offer===v},M.subscription.offer===v?'selected':'')).join('')}</fieldset>`+A('Choisir Premium — démo','subscribe')+A('Continuer en découverte','premium-return',{},'text-button mt')+note('Offre et prix fictifs. Tous les parcours sont ouverts pour tester ce prototype. Aucun débit, essai automatique ou renouvellement réel.')+moreActions(B('Restaurer mon accès','PRE-04','secondary')+B('Détails de l’offre','PRF-11','text-button mt',{document:'Abonnement'})),
 'PRE-03':()=>head(M.subscription.status==='active'?'Votre accès démo est actif':M.subscription.status==='pending'?'Confirmation en attente':'L’accès n’est pas confirmé')+icon(M.subscription.status==='active'?'check':M.subscription.status==='pending'?'more':'x','success-icon')+panel(P(subscriptionLabel())+P(M.subscription.status==='active'?'Vous pouvez reprendre le contenu que vous consultiez. Aucun abonnement réel n’a été créé.':'Une attente ou un échec ne vaut pas validation. Aucun montant n’a été prélevé.'))+(M.subscription.status==='pending'?A('Vérifier le statut — simulation','subscription-check'):M.subscription.status==='active'?A('Reprendre mon parcours','premium-return'):B('Réessayer','PRE-01'))+B('Besoin d’aide','PRF-10','text-button mt'),
 'PRE-04':()=>head('Retrouver mon accès','Aucun nouvel achat')+panel(`<h3>${esc(M.profile.email||'Mon compte de démonstration')}</h3>${P(M.restoreStatus||'Vérifiez si un accès Premium est associé à ce compte.')}`)+A('Vérifier mon accès — démo','restore-access')+B('Mon abonnement','PRF-06','secondary mt')+B('Changer de compte','ENT-06','text-button mt')+MOCK_NOTICE,
});
Object.assign(ACTIONS,{
 'account-cancel':()=>{M.pendingProfile=null;returnToState(M.accountReturnState,M.accountReturn||'ACC-01');M.accountReturnState=null;M.accountReturn=null;},
 'resend-code':()=>toast('Le code de démonstration reste 123456. Aucun email envoyé.'),
 'avatar-remove-request':()=>confirmAction('Retirer ma photo de profil ?','Les photos utilisées dans vos analyses ne seront pas supprimées.','avatar-remove'),
 'avatar-remove':()=>{M.profileEdit||=clone(M.profile);M.profileEdit.avatar='';closeModal();render();},
 'clear-prefs-request':()=>confirmAction('Retirer mes préférences ?','Les comptes rendus historiques garderont les choix utilisés lors de leur création.','clear-prefs'),
 'clear-prefs':()=>{M.prefs=initial().prefs;M.preferenceEdit=clone(M.prefs);clearDrafts('preferences');closeModal();render();},
 'logout-request':()=>confirmAction('Se déconnecter ?','Vos données conservées sur cet appareil ne seront pas supprimées.','logout'),
 logout:()=>{M.profile.connected=false;closeModal();go('ENT-06');},
 'send-support':()=>{const t={...M.supportDraft,ref:'MSG-'+String(M.tickets.length+1).padStart(4,'0')};M.tickets.push(t);closeModal();render();toast('Votre demande a été enregistrée sur cet appareil.');},
 'premium-from':d=>{M.context.returnTo=d.return||route;go('PRE-01');},
 'premium-return':()=>{const s=M.premiumReturnState;M.premiumReturnState=null;returnToState(s,M.context.returnTo||'ACC-01');},
 offer:d=>{M.subscription.offer=d.value;render();},
 subscribe:()=>{M.subscription.status=M.scenario==='error'?'failed':M.scenario==='pending'?'pending':'active';go('PRE-03');},
 'subscribe-pending':()=>{M.subscription.status='pending';go('PRE-03');},
 'subscribe-failed':()=>{M.subscription.status='failed';go('PRE-03');},
 'subscription-check':()=>{M.subscription.status='active';M.scenario='normal';render();},
 restore:d=>{M.restoreStatus=({found:'Droits de démonstration retrouvés.',none:'Aucun droit retrouvé dans ce scénario.',error:'Erreur simulée. Vous pouvez réessayer.'})[d.result];if(d.result==='found')M.subscription.status='active';render();},
 'manage-subscription':()=>modal('Gérer mon abonnement',P(M.subscription.status==='cancelled'?'Renouvellement désactivé.':'Beautify Plus actif.')+(M.subscription.status==='cancelled'?'':A('Désactiver le renouvellement','subscription-status',{status:'cancelled'},'secondary'))),
 'subscription-status':d=>{M.subscription.status=d.status;closeModal();render();},
 'execute-data':()=>{const op=M.dataOperation;if(!op)return;const map={Profil:['profile'],Préférences:['prefs'],Photos:['photos'],Rapports:['analyses'],Essais:['simulations'],Suivi:['sessions','observations','goals','dayNotes'],Enregistrés:['saved','collections'],Événements:['events'],Routines:['routines','active','schedules','skinCareProducts','reminders'],Dressing:['clothes','outfits'],Commandes:['orders','cart','checkout']};if(op.type==='Exporter'){const out={type:'Beautify — export de données',date:new Date().toISOString()};op.categories.forEach(c=>(map[c]||[]).forEach(k=>out[k]=k==='photos'?{count:Object.keys(memoryPhotos).length,note:'Images non incluses.'}:M[k]));if(op.categories.includes('Routines'))out.actions=M.actions.filter(a=>a.kind==='routine');const url=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='beautify-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);M.dataStatus='Votre export a été préparé.';}else{const defaults=initial();op.categories.forEach(c=>{if(c==='Routines'){M.routines=[];M.active=[];M.schedules={};M.skinCareProducts=[];M.skinRoutineIds={};M.analyses.filter(record=>record.domain==='Peau').forEach(record=>record.skinRoutineStatus='removed');M.skinProductPicker=null;M.skinPlanReview=null;M.skinRemoved=null;M.actions=M.actions.filter(a=>a.kind!=='routine');M.skippedOccurrences=[];clearDrafts('routine');M.routineEdit=null;}else if(c==='Photos'){Object.values(memoryPhotos).forEach(u=>URL.revokeObjectURL(u));Object.keys(memoryPhotos).forEach(k=>delete memoryPhotos[k]);M.profile.avatar='';M.draft.photo='';M.simulationPhoto='';M.context.observationPhoto='';M.context.clothingPhoto='';M.analyses.forEach(x=>x.photo='');M.observations.forEach(x=>x.photo='');M.clothes.forEach(x=>{if(x.image?.startsWith('photo-'))x.image='';});M.simulations.forEach(x=>x.source='');M.simulationDraft=null;}else (map[c]||[]).forEach(k=>M[k]=['profile','prefs','checkout'].includes(k)?clone(defaults[k]):Array.isArray(defaults[k])?[]:{});if(c==='Essais'){M.context.simulation=null;M.haircutDraft=null;M.simulationPhoto='';}if(c==='Rapports'){M.hairProfile=null;M.colorProfile=null;M.skinProfile=null;M.skinPlan=null;M.skinPlanReview=null;M.previewSeason=null;M.savedSeason=false;M.draft=clone(defaults.draft);M.context.analysis=null;M.messages=M.messages.filter(m=>m.objectKey!=='analysis');M.comparison=null;}if(c==='Préférences'){M.contentFeedback={};M.preferenceEdit=clone(M.prefs);clearDrafts('preferences');}if(c==='Suivi'){M.observationEdit=null;M.goalEdit=null;clearDrafts('observation');clearDrafts('goal');clearDrafts('day-note');}});M.saved=M.saved.filter(id=>item(id));M.collections.forEach(c=>c.items=c.items.filter(id=>item(id)));M.dataStatus='Données retirées : '+op.categories.join(', ')+'.';}M.dataOperation=null;closeModal();if(op.type==='Exporter')render();else go('PRF-08',{reset:true});toast(M.dataStatus);},
});
Object.assign(F,{
 'register':d=>{if(!d.terms)return formError('Confirmez le fonctionnement de ce compte démo.');M.pendingProfile={...(M.profileEdit||M.profile),name:d.name,email:d.email};go('ENT-07');},
 'login':d=>{M.pendingProfile={...M.profile,email:d.email};go('ENT-07');},
 'verify':d=>{if(d.code!=='123456'||M.scenario==='refused')return formError('Le code est incorrect. Le code de démonstration est 123456.');M.profile={...(M.pendingProfile||M.profile),connected:true};M.pendingProfile=null;returnToState(M.accountReturnState,M.accountReturn||'ACC-01');M.accountReturnState=null;M.accountReturn=null;toast('Accès démo vérifié.');},
 'recover':d=>{M.pendingProfile={...M.profile,email:d.email};modal('Retrouver mon accès',P('Aucun email n’a été envoyé. Ce bouton représente le lien de récupération.')+B('Poursuivre — démo','ENT-07')+B('Retour à la connexion','ENT-06','secondary mt'));},
 'profile':d=>{if(d.email!==M.profile.email&&d.email){M.pendingProfile={...(M.profileEdit||M.profile),name:d.name,email:d.email};M.accountReturnState={...snapshot(),route:'PRF-01',scroll:0};go('ENT-07');}else{Object.assign(M.profile,M.profileEdit||{},d);M.profileEdit=null;go('PRF-01');toast('Profil mis à jour.');}},
 reminders:d=>{if(d.routine&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(d.routineTime||''))return formError('Choisissez une heure valide pour votre rappel.');M.reminders={...M.reminders,routine:!!d.routine,routineTime:d.routineTime||M.reminders.routineTime||'08:00'};clearDrafts('reminders');go('ROU-01',{replace:true});toast('Préférence de rappel enregistrée.');},
 'data':d=>{const selected=Object.keys(d).filter(k=>k.startsWith('data')&&d[k]).map(k=>k.slice(4));if(!selected.length)return formError('Choisissez au moins une catégorie.');M.dataOperation={type:d.operation,categories:selected};confirmAction(d.operation==='Exporter'?'Exporter ces données ?':'Retirer ces données ?',selected.join(', ')+'. Les autres catégories seront conservées.','execute-data');},
 'delete-account':d=>{if(d.confirmation!=='SUPPRIMER')return formError('Écrivez exactement SUPPRIMER.');Object.values(memoryPhotos).forEach(u=>URL.revokeObjectURL(u));Object.keys(memoryPhotos).forEach(k=>delete memoryPhotos[k]);M=initial();go('ENT-02',{reset:true});toast('Vos données locales ont été supprimées.');},
 'support':(d,f)=>{if(!d.message?.trim())return formError('Décrivez votre demande en quelques mots.');const file=f?.elements?.attachment?.files?.[0];if(file?.size>5*1024*1024)return formError('La pièce jointe doit faire moins de 5 Mo.');M.supportDraft={topic:d.topic,message:d.message,attachment:file?.name||''};modal('Vérifier ma demande',P('<strong>'+esc(d.topic)+'</strong>')+P(esc(d.message))+P('Pièce jointe : '+esc(file?.name||'aucune'))+A('Confirmer la demande — démo','send-support')+MOCK_NOTICE);},
});

ACTIONS['restore-access']=()=>ACTIONS.restore({result:M.scenario==='error'?'error':M.subscription.status==='active'?'found':'none'});
